"OLAYLAR_DUNYA_AVRUPA_MO:-0593-01-01:0":{"b": ["آرخونی سولون و اصلاحات سایساختهایا", "705d0dbf"], "d": ["اصلاحاتی که بردگی بدهی را برانداخت؛ طبقات شهروندی از نو سامان یافت.", "6d544b32"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0594-01-01:0":{"b": ["جنگ مقدس نخست: کیرها ویران شد، دلفی به نظارت امفیکتیونی درآمد", "e01a15f5"], "d": ["برای دسترسی به دلفی، کیرها نابود شد.", "1ad355f7"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0597-01-01:0":{"b": ["کامارینا به دست سیراکوز بنیان یافت", "47055e49"], "d": ["سیراکوز در جنوب‌خاوری مستعمره بنیان نهاد (135 سال پس از سیراکوز).", "40d8cb35"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0599-01-01:0":{"b": ["پوسیدونیا (پایستوم) به دست سیباریسی‌ها بنیان یافت", "5a2f0a73"], "d": ["سیباریس در کرانهٔ تیرنی مستعمره بنیان نهاد.", "3a48417e"]},
