"OLAYLAR_DUNYA_AVRUPA_MO:-0646-01-01:0":{"b": ["اولبیا/برزان به دست میلتوس بنیان یافت", "c05a7313"], "d": ["نخستین سکونتگاه یونانی در شمال دریای سیاه.", "5e2f8c3f"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0656-01-01:0":{"b": ["کیپسلوس ستمگری را در کورنت برپا کرد، باکخیادای برافتاد", "f4f32246"], "d": ["کیپسلوس الیگارشی باکخیادای را برانداخت و ستمگری درازمدتی برپا کرد.", "790b64e0"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0668-01-01:0":{"b": ["نبرد هیسیایی: آرگوس زیر فرمان فیدون اسپارت را شکست داد", "47a0d03b"], "d": ["برتری آرگوس در دورهٔ فیدون (تاریخ و تاریخی‌بودن محل بحث است).", "c3d09b3d"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0672-01-01:0":{"b": ["لوکروی اپیزفیریوی (ایتالیای جنوبی) بنیان یافت", "1ca3a23e"], "d": ["مستعمره در ایتالیای جنوبی.", "2471ca1e"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0684-01-01:0":{"b": ["جنگ دوم مسنیا آغاز شد", "760d8edb"], "d": ["اسپارت شورش مسنیا را سرکوب کرد و نظام هلوت را استوار ساخت.", "7f1466e7"]},
